module.exports=[32826,a=>{"use strict";a.i(5649);let b=[{id:"controle-hydraulique",title:"Contrôle-Commande Temps Réel, Procédé Hydraulique Bicuve",slug:"controle-hydraulique-bicuve-2026",year:2026,category:"Automatisme & Régulation",shortDescription:"De la modélisation Matlab/Simulink au pilotage temps réel sur cible industrielle Speedgoat.",detailedDescription:"Projet complet d'automatique portant sur un système hydraulique à deux cuves couplées. De la modélisation physique et l'analyse de stabilité jusqu'au déploiement d'un régulateur numérique en temps réel sur une cible Speedgoat, en passant par l'identification expérimentale et la synthèse de correcteurs continus et discrets.",technicalChallenges:"Modélisation physique et analyse de stabilité (critère de Routh-Hurwitz). Identification expérimentale sur système réel (gain, constante de temps par réponse indicielle). Synthèse de régulateurs continus et numériques, en régulation cascade double boucle. Déploiement temps réel HIL sur cible Speedgoat (période d'échantillonnage 10ms). Résultats mesurés : temps de réponse divisé par 4 en boucle fermée, erreur statique annulée, robustesse validée face aux perturbations.",impact:"Temps de réponse divisé par 4 en boucle fermée, erreur statique annulée et robustesse de régulation validée sur banc d'essai matériel.",technologies:["Matlab/Simulink","Régulation P/PI/PID/Cascade","HIL Speedgoat"],themeColor:{r:99,g:102,b:241},coverImage:"/image/projects/controle-hydraulique-cover.webp",gallery:["/image/projects/controle-hydraulique-cover.webp","/image/projects/controle-hydraulique-pi-discret.webp","/image/projects/controle-hydraulique-selecteur-config.webp","/image/projects/controle-hydraulique-selecteur-systeme.webp"]},{id:"filtre-tchebychev",title:"Filtre Passe-Bas Actif de Tchebychev",slug:"filtre-tchebychev-2026",year:2026,category:"Électronique",shortDescription:"De l'équation à la carte électronique fonctionnelle, conception, simulation et fabrication d'un filtre analogique.",detailedDescription:"Conception complète d'un filtre passe-bas actif d'ordre 4 de type Tchebychev, depuis la synthèse analytique jusqu'à la fabrication physique du PCB. Le projet inclut l'étude comparative Butterworth/Tchebychev, la simulation LTSpice, le routage KiCad complet et la caractérisation à l'oscilloscope du prototype final.",technicalChallenges:"Synthèse analytique d'un filtre d'ordre 4 (comparaison Butterworth/Tchebychev) respectant un cahier des charges strict (bande passante 4,5 kHz, ondulation ≤1dB, atténuation 35dB à 13kHz). Simulation complète sous LTSpice avant fabrication. Routage KiCad de bout en bout : schéma, empreintes CMS, plan de masse, DRC, export Gerber. Fabrication physique : gravure CNC, soudure CMS, caractérisation à l'oscilloscope. Travail en binôme avec analyse comparative de deux réalisations indépendantes.",impact:"Prototype matériel entièrement fonctionnel, respectant strictement la fréquence de coupure à 4,5 kHz avec une atténuation effective de 35dB mesurée à l'oscilloscope.",technologies:["LTSpice","KiCad","Cellules Sallen-Key","Gravure CNC"],themeColor:{r:6,g:182,b:212},coverImage:"/image/projects/filtre-tchebychev-cover.webp"},{id:"lyngk",title:"Lyngk – Moteur de Jeu Hexagonal",slug:"lyngk-moteur-jeu-c-2026",year:2026,category:"Algorithmique",shortDescription:"Moteur de jeu de plateau hexagonal en C, entre rigueur bas niveau et algorithmique combinatoire.",detailedDescription:"Développement complet en langage C d'un moteur de jeu reproduisant fidèlement la mécanique du jeu de plateau Lyngk. L'architecture MVC stricte, avec modèle en Singleton, assure une séparation rigoureuse entre logique de jeu, rendu graphique SDL3 et gestion des entrées. Le plateau hexagonal est traité en coordonnées axiales avec un algorithme DFS pour le calcul de trajectoires.",technicalChallenges:"Architecture MVC stricte (modèle en Singleton) pour un code maintenable. Optimisation bas niveau par bitmasking : 43 cases de plateau traitées en un seul cycle via registres 64 bits. Algorithme DFS pour le calcul de trajectoires en coordonnées axiales hexagonales. Gestion mémoire stricte : zéro fuite, compilation propre sous -Wall -Wextra. IA adverse (PvE) modélisée en machine d'état, sélection de coup en complexité O(1).",impact:"Moteur de jeu complet sans aucune fuite mémoire, permettant une résolution d'état asymétrique continue avec une complexité opérationnelle minimale.",technologies:["C","SDL3","Architecture MVC","DFS"],themeColor:{r:234,g:179,b:8},coverImage:"/image/projects/lyngk-cover.webp",gallery:["/image/projects/lyngk-cover.webp","/image/projects/lyngk-code.webp","/image/projects/lyngk-victory.webp"]},{id:"microprocesseurs",title:"Microprocesseurs & Programmation Bas Niveau",slug:"microprocesseurs-atmega2560-2026",year:2026,category:"Informatique Bas Niveau",shortDescription:"Trois systèmes embarqués en assembleur pur, sans aucune abstraction logicielle.",detailedDescription:"Développement de trois systèmes embarqués complets programmés exclusivement en assembleur AVR8 sur microcontrôleur ATMEGA2560, sans aucune bibliothèque ni abstraction logicielle. Chaque système exploite directement les registres matériels, les interruptions et les périphériques du microcontrôleur.",technicalChallenges:"Compteur piloté par interruptions, avec mode veille pour l'économie d'énergie (zéro polling). Capteur de température interrogeable à distance, combinant CAN + port parallèle + USART simultanément. Système de détection d'intrusion (capteurs de distance, clavier matriciel, gestion d'événements concurrents type IoT).",impact:"Trois systèmes critiques (supervision, mesure de température embarquée, capteurs temps réel) développés avec une efficience mémoire native et une stabilité absolue des interruptions.",technologies:["ASM AVR8","ATMEGA2560","CAN","USART"],themeColor:{r:239,g:68,b:68},coverImage:"/image/projects/microprocesseurs-cover.webp",gallery:["/image/projects/microprocesseurs-cover.webp","/image/projects/microprocesseurs-temperature-ihm.webp"]},{id:"robotino",title:"Robotino – Hockey Autonome",slug:"robotino-hockey-autonome-2026",year:2026,category:"Systèmes Embarqués",shortDescription:"Programmation d'un robot mobile omnidirectionnel pour un match de hockey entièrement autonome : vision, navigation et tir.",detailedDescription:"Conception complète du système de contrôle d'un Robotino 2 pour un match de hockey robotisé. Le robot devait repérer un palet par vision embarquée, naviguer vers le but en évitant les robots adverses, détecter la ligne de but métallique par capteur inductif et déclencher un tir précis. L'architecture de contrôle repose sur un Grafcet hiérarchique orchestrant navigation, évitement d'obstacles temps réel et séquence de tir.",technicalChallenges:"La détection colorimétrique initiale en espace RGB générait des pertes de cible face aux variations lumineuses. Le basculement vers l'espace HSV a isolé la teinte de la luminosité pour un suivi robuste. La portée très courte du capteur inductif (4 mm) entraînait des dépassements de cible à cause de l'inertie. Une anticipation de freinage via odométrie (2000 impulsions/tour) et vision a résolu le problème. La zone fiable des infrarouges (15-45 cm) a été modélisée pour éviter les faux positifs au-delà de 50 cm.",impact:"Système de vision et de tir fiabilisé en conditions réelles de match, avec un suivi de palet robuste malgré les variations lumineuses et un tir déclenché sans dépassement de cible.",technologies:["Robotino 2","Grafcet","Vision par Ordinateur","Capteurs Industriels","Robotino View","Automatique"],themeColor:{r:66,g:133,b:196},coverImage:"/image/projects/robotino-cover.webp"},{id:"awale",title:"Awale - Stratégie en C",slug:"awale-jeu-c-2026",year:2026,category:"Algorithmique",shortDescription:"Développement du jeu de société traditionnel en langage C axé sur l'efficacité des structures.",detailedDescription:"Conception architecturale et implémentation en langage formel C de la mécanique combinatoire du jeu de société Awale. Ce projet focalise principalement sur la performance algorithmique pure, la gestion déterministe de la mémoire et la logique d'état asymétrique continue.",technicalChallenges:"La difficulté majeure résidait dans la modélisation mathématique d'un plateau de jeu strictement cyclique sans causer de débordement dynamique en mémoire vive. L'approche d'ingénierie a consisté à encapsuler le plateau dans des structures de données contiguës, manipulées perpétuellement via l'arithmétique modulaire et des pointeurs de fonctions robustes.",impact:"Moteur de jeu s'exécutant dans un espace mémoire strictement borné, sans dépassement ni fuite, validé sur l'ensemble des scénarios de partie cyclique.",technologies:["C","Logique de Jeu","Pointeurs C","Arithmétique Modulaire"],themeColor:{r:196,g:87,b:76}},{id:"pygroove",title:"PyGroove - Assistant Musical",slug:"pygroove-assistant-audio-2025",year:2025,category:"Développement Logiciel",shortDescription:"Lecteur musical intelligent en Python doté de reconnaissance vocale et de rendu audio synchrone.",detailedDescription:"Création d'un environnement de lecture multimédia intelligent programmé entièrement en Python. Le système orchestre une interface vectorielle complexe sous Tkinter, délègue le rendu bas niveau au moteur Pygame, intègre le protocole de reconnaissance vocale Speech-Recognition, et procède au parsing de métadonnées audio via les algorithmes Pydub et Mutagen.",technicalChallenges:"Gérer la concurrence critique d'accès matériels simultanés entre la boucle d'événements visuels, le thread d'écoute réseau asynchrone et le buffer DMA matériel de la carte son. La solution logicielle a impliqué une séparation d'E/S (Entrées/Sorties) au sein d'une architecture multi-threadée stricte pour isoler les instructions temps réel du wrapper asynchrone.",impact:"Application stable en usage prolongé : lecture audio, reconnaissance vocale et interface graphique tournent simultanément sans blocage ni conflit d'accès matériel.",technologies:["Python","Tkinter","Pygame","Speech-Recognition","Pydub","Mutagen"],themeColor:{r:196,g:150,b:74},coverImage:"/image/projects/pygroove-cover.webp"},{id:"terminal-c",title:"Shell Unix - Interpréteur C",slug:"interpreteur-commandes-unix-2025",year:2025,category:"Systèmes Embarqués",shortDescription:"Développement natif complet d'un émulateur de terminal en langage C s'adossant aux appels Unix/Linux.",detailedDescription:"Ingénierie inverse d'un shell applicatif standard par la manipulation intime des appels système au niveau de l'espace noyau (Kernel Space). Ce projet requiert une compréhension profonde de la mémoire paginée (Heap), la duplication de processus système ainsi que l'interfaçage des descripteurs de fichiers.",technicalChallenges:"La communication asynchrone et imprévisible inter-processus a provoqué des instabilités dans les flux d'entrées/sorties lors de la propagation du signal matériel. L'exécution sécurisée fut garantie par le déploiement d'un gestionnaire de signaux déterministes et la gestion méthodique des pipelines en mémoire vive (fork, execvp et dup2).",impact:"Shell capable d'exécuter des chaînes de commandes complexes (pipes, redirections) de façon stable, sans fuite de processus ni instabilité liée aux signaux système.",technologies:["C","Processus Posix","Linux Kernel","Signaux ASync","Mémoire"],themeColor:{r:85,g:98,b:115}},{id:"ferme-poo",title:"Simulateur Agricole C++",slug:"simulateur-agricole-poo-2024",year:2024,category:"Développement Logiciel",shortDescription:"Application modélisée en C++ démontrant la rigueur des patrons de conception majeurs (POO).",detailedDescription:"Modélisation en C++ d'un environnement systémique simulé. Le paradigme Orienté Objet est exploité de fond en comble pour assurer un isolement strict des responsabilités par l'héritage d'interfaces, le polymorphisme applicatif et la compartimentation spatiale des objets d'activité.",technicalChallenges:"L'instabilité inhérente aux pointeurs orphelins (Dangling Pointers) au sein d'une topologie circulaire forte a compromis initialement la destruction des entités par le processus courant. L'ingénierie moderne en C++ a remédié au conflit en déployant un écosystème de pointeurs intelligents gérant structurellement le cycle de vie mémoire via le comptage de références.",impact:"Architecture 100% exempte de fuite mémoire malgré une topologie d'objets fortement circulaire, grâce à une gestion du cycle de vie par pointeurs intelligents.",technologies:["C++","POO","Polymorphisme","Héritage ISO","Smart Pointers"],themeColor:{r:58,g:148,b:137}},{id:"snake",title:"Snake - Moteur Arcade C++",slug:"moteur-jeu-snake-cpp-2024",year:2024,category:"Algorithmique",shortDescription:"Conception architecturale en C++ encadrant la complexité d'une boucle vidéo temps réel.",detailedDescription:"Développement fonctionnel d'un moteur d'arcade limitant la surcharge du microprocesseur selon des principes stricts de la POO. Implémentation isolée de la game loop principale, abstraction du module des entrées matérielles, et raffinement algorithmique pour la vérification collisionnelle 2D.",technicalChallenges:"La chute du taux de rafraîchissement (frame rate drops) occasionnait des erreurs silencieuses dans le registre de vérifications d'intersections vectorielles à haute vélocité. Le correctif a dicté l'adoption d'un diviseur d'échelle temporel interpolé (Delta-time scaling) garantissant une cohérence arithmétique mathématiquement indépendante de la bande passante du processeur local.",impact:"Boucle de jeu maintenant une fréquence stable et une détection de collision fiable, indépendamment de la puissance du processeur cible.",technologies:["C++","Architecture Objet","Algorithmique Matérielle","Game Loop"],themeColor:{r:140,g:95,b:168}},{id:"budget",title:"Analyse Financière Python",slug:"script-analyse-financiere-2024",year:2024,category:"Développement Logiciel",shortDescription:"Script algorithmique automatisant le traitement systématique de vastes cohortes de données statistiques mensuelles.",detailedDescription:"Conception et écriture d'une tuyauterie de données (data pipeline) robuste en Python. Ce module opère au travers de bibliothèques d'analyse complexes pour extraire, uniformiser, et générer mathématiquement des tracés graphiques interactifs en vue de synthèses prédictives.",technicalChallenges:"La lenteur systémique de compilation générée par la traversée bouclée d'enregistrements historiques massifs limitait l'utilisation instantanée de la vue interface. La restructuration informatique a introduit une vectorisation matricielle stricte de toutes les manipulations, combinée à une sauvegarde délocalisée du tracé en tampons SVG/Canvas pré-rendus.",impact:"Temps de traitement des cohortes de données mensuelles réduit significativement grâce à la vectorisation, avec restitution graphique quasi instantanée.",technologies:["Python","Analytique Data","Scripts","Vectorisation","Graphes ML"],themeColor:{r:122,g:140,b:74}},{id:"voiture-bluetooth",title:"Robot Mobile Bluetooth",slug:"vehicule-embarque-bluetooth-2023",year:2023,category:"Systèmes Embarqués",shortDescription:"Déploiement en tant que Chef de Projet d'un système matériel piloté via Arduino (C/C++).",detailedDescription:"Ingénierie complète intégrée, couvrant l'analyse CAO et modélisation via CATIA V5, en tandem formel avec l'impression 3D paramétrique du bâti asymétrique de mobilité. Développement microcontrôlé en C/C++ (Arduino) de la chaîne de régulation motrice ainsi que de l'antenne logique de communication Bluetooth RX/TX bidirectionnelle.",technicalChallenges:"Une sollicitation d'intensité hors normes au démarrage des unités moteurs provoquait d'importants creux de tension capacitifs perturbant directement les calculs logiques embarqués (brownouts hardware). L'architecture a été solidifiée grâce à un isolement galvanique partiel par optocoupleur et l'optimisation mathématique du routage de puissance via les signaux de commande en PWM (Pulse Width Modulation).",impact:"Robot livré et fonctionnel en conditions réelles, avec chaîne motrice stabilisée contre les micro-coupures de tension et liaison Bluetooth bidirectionnelle fiable.",technologies:["C/C++","Arduino µC","CATIA V5","Bluetooth RF","Mécanique 3D"],themeColor:{r:93,g:101,b:168}}];async function c(){return b.map(a=>({slug:a.slug}))}function d({children:a}){return a}a.s(["default",()=>d,"generateStaticParams",()=>c],32826)}];

